#include "azureus_remote_diversification.hpp"
#include "file_io.hpp"
#include <set>
#include <algorithm>
#include <cerrno>
#include <fcntl.h>
#include <linux/fs.h>
#include <sys/stat.h>
#include <unistd.h>
namespace biglybtc::storage {
namespace {
using detail::Descriptor;using Record=core::AzureusRemoteDiversification;
auto err(ErrorCode code,const char* message){return std::unexpected(Error{code,message});}
bool same(const struct stat& a,const struct stat& b){return a.st_dev==b.st_dev&&a.st_ino==b.st_ino&&a.st_mode==b.st_mode&&a.st_uid==b.st_uid&&a.st_nlink==b.st_nlink&&a.st_size==b.st_size&&a.st_mtim.tv_sec==b.st_mtim.tv_sec&&a.st_mtim.tv_nsec==b.st_mtim.tv_nsec&&a.st_ctim.tv_sec==b.st_ctim.tv_sec&&a.st_ctim.tv_nsec==b.st_ctim.tv_nsec;}
bool named(int parent,const std::string& name,int fd){struct stat a{},b{};return ::fstat(fd,&a)==0&&::fstatat(parent,name.c_str(),&b,AT_SYMLINK_NOFOLLOW)==0&&S_ISDIR(a.st_mode)&&S_ISDIR(b.st_mode)&&a.st_uid==::geteuid()&&a.st_dev==b.st_dev&&a.st_ino==b.st_ino;}
struct Paths {std::shared_ptr<const ProfileLease> lease;Descriptor dht{-1},net{-1};std::string network;int dir()const{return network.empty()?dht.get():net.get();}bool current()const{return named(lease->directoryHandle(),"dht",dht.get())&&(network.empty()||named(dht.get(),network,net.get()));}};
std::expected<Paths,Error> paths(const AzureusValueVersions& versions){auto lease=versions.retainProfile();if(!lease){return std::unexpected(lease.error());}Paths p;p.lease=*lease;p.dht=Descriptor(::openat(p.lease->directoryHandle(),"dht",O_RDONLY|O_DIRECTORY|O_CLOEXEC|O_NOFOLLOW));if(versions.network()){p.network="net"+std::to_string(versions.network());p.net=Descriptor(::openat(p.dht.get(),p.network.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC|O_NOFOLLOW));}if(!p.current()){return err(ErrorCode::UnsafePath,"Unsafe Azureus diversification directory");}return p;}
struct Capture {std::optional<std::string> bytes;std::optional<struct stat> stamp;};
std::expected<Capture,Error> capture(int fd,const char* name){Capture c;struct stat s{};if(::fstatat(fd,name,&s,AT_SYMLINK_NOFOLLOW)==0){if(!S_ISREG(s.st_mode)||s.st_uid!=::geteuid()||s.st_nlink!=1){return err(ErrorCode::UnsafePath,"Unsafe Azureus diversification file");}c.stamp=s;}else if(errno!=ENOENT){return err(ErrorCode::Io,"Cannot inspect Azureus diversification file");}auto bytes=detail::readFile(fd,name,compatibleConfigLimits().inputBytes);if(!bytes){return std::unexpected(bytes.error());}c.bytes=std::move(*bytes);struct stat after{};const bool present=::fstatat(fd,name,&after,AT_SYMLINK_NOFOLLOW)==0;if(!present&&errno!=ENOENT){return err(ErrorCode::Io,"Cannot recheck Azureus diversification file");}if(present!=c.stamp.has_value()||present!=c.bytes.has_value()||(present&&!same(*c.stamp,after))){return err(ErrorCode::Conflict,"Azureus diversification changed while reading");}return c;}
bool equal(const Capture& a,const Capture& b){return a.bytes==b.bytes&&a.stamp.has_value()==b.stamp.has_value()&&(!a.stamp||same(*a.stamp,*b.stamp));}
std::expected<core::Document,Error> parse(std::string bytes){auto d=core::Document::parse(std::move(bytes),compatibleConfigLimits());if(!d||d->root().type!=core::Node::Type::Dictionary){return err(ErrorCode::InvalidFormat,"Invalid Azureus diversification map");}std::set<std::string_view> keys;for(std::size_t i=0;i<d->root().children.size();i+=2){if(!keys.insert(d->root().children[i].bytes).second){return err(ErrorCode::InvalidFormat,"Duplicate Azureus diversification map key");}}if(const auto* remote=d->find("remote");remote&&remote->type!=core::Node::Type::List){return err(ErrorCode::InvalidFormat,"Invalid Azureus remote diversification list");}return std::move(*d);}
std::optional<Record> record(const core::Node& n){if(n.type!=core::Node::Type::Dictionary){return {};}const auto* key=n.find("key"),*type=n.find("type"),*exp=n.find("exp"),*fpo=n.find("fpo");if(!key||key->type!=core::Node::Type::Bytes||key->bytes.size()!=20||!type||type->type!=core::Node::Type::Integer||(type->integer!=2&&type->integer!=3)||!exp||exp->type!=core::Node::Type::Integer||!fpo||fpo->type!=core::Node::Type::List||fpo->children.size()!=2){return {};}Record r;std::copy_n(reinterpret_cast<const std::uint8_t*>(key->bytes.data()),20,r.key.begin());r.type=std::int8_t(type->integer);r.expiry=exp->integer;for(unsigned i=0;i<2;++i){const auto& v=fpo->children[i];if(v.type!=core::Node::Type::Integer||v.integer<0||v.integer>=10){return {};}r.offsets[i]=unsigned(v.integer);}if(r.offsets[0]==r.offsets[1]){return {};}return r;}
std::string encoded(const Record& r){return "d3:expi"+std::to_string(r.expiry)+"e3:fpoli"+std::to_string(r.offsets[0])+"ei"+std::to_string(r.offsets[1])+"ee3:key20:"+std::string(reinterpret_cast<const char*>(r.key.data()),20)+"4:typei"+std::to_string(r.type)+"ee";}
}
std::expected<std::vector<core::AzureusRemoteDiversification>,Error> readAzureusRemoteDiversifications(const AzureusValueVersions& versions,std::int64_t now){try{auto p=paths(versions);if(!p){return std::unexpected(p.error());}auto access=p->lease->sourceAccess();if(!access){return std::unexpected(access.error());}auto primary=capture(p->dir(),"diverse.dat"),pending=capture(p->dir(),"diverse.saving");if(!primary){return std::unexpected(primary.error());}if(!pending){return std::unexpected(pending.error());}auto doc=parse(primary->bytes.value_or(pending->bytes.value_or("de")));if(!doc){return std::unexpected(doc.error());}std::vector<core::AzureusRemoteDiversification> out;if(const auto* remote=doc->find("remote")){for(const auto& node:remote->children){auto item=record(node);if(item&&item->expiry>now){out.push_back(*item);}}}if(!p->current()){return err(ErrorCode::Conflict,"Azureus diversification directory changed");}return out;}catch(...){return err(ErrorCode::Io,"Cannot read Azureus remote diversifications");}}
std::expected<void,Error> saveAzureusRemoteDiversifications(const AzureusValueVersions& versions,std::span<const core::AzureusRemoteDiversification> updates){try{if(updates.empty()){return {};}if(updates.size()>512){return err(ErrorCode::InvalidFormat,"Too many Azureus diversification updates");}for(const auto& r:updates){if((r.type!=2&&r.type!=3)||r.expiry<=0||r.offsets[0]>=10||r.offsets[1]>=10||r.offsets[0]==r.offsets[1]){return err(ErrorCode::InvalidFormat,"Invalid Azureus diversification update");}}auto p=paths(versions);if(!p){return std::unexpected(p.error());}auto access=p->lease->sourceAccess(true);if(!access){return std::unexpected(access.error());}auto primary=capture(p->dir(),"diverse.dat"),pending=capture(p->dir(),"diverse.saving");if(!primary){return std::unexpected(primary.error());}if(!pending){return std::unexpected(pending.error());}if(pending->bytes){return err(ErrorCode::Conflict,"Review pending Azureus diversification publication");}auto doc=parse(primary->bytes.value_or("de"));if(!doc){return std::unexpected(doc.error());}std::set<std::array<std::uint8_t,20>> written;std::string list="l";if(const auto* remote=doc->find("remote")){for(const auto& node:remote->children){auto old=record(node);const auto found=old?std::ranges::find(updates,old->key,&Record::key):updates.end();if(found!=updates.end()){if(written.insert(found->key).second){list+=encoded(*found);}}else{auto unchanged=core::encodeValue(node);if(!unchanged){return err(ErrorCode::InvalidFormat,"Cannot retain Azureus diversification entry");}list+=*unchanged;}}}for(const auto& r:updates){if(written.insert(r.key).second){list+=encoded(r);}}list+='e';if(!doc->replaceValue("remote",list)){return err(ErrorCode::InvalidFormat,"Cannot merge Azureus diversifications");}const auto bytes=doc->serialize();auto created=detail::writeExclusiveOwned(p->dir(),"diverse.saving",bytes,0600);if(!created){return std::unexpected(created.error());}auto live=capture(p->dir(),"diverse.dat"),temp=capture(p->dir(),"diverse.saving");struct stat fd{};if(!live||!temp||!equal(*primary,*live)||!temp->bytes||*temp->bytes!=bytes||!temp->stamp||::fstat(created->get(),&fd)!=0||!same(fd,*temp->stamp)||!p->current()||!versions.validate()){return err(ErrorCode::Conflict,"Azureus diversification preimage changed");}if(::renameat2(p->dir(),"diverse.saving",p->dir(),"diverse.dat",primary->bytes?0:RENAME_NOREPLACE)!=0||::fsync(p->dir())!=0){return err(ErrorCode::Io,"Cannot publish Azureus diversifications");}auto published=capture(p->dir(),"diverse.dat");if(!published||published->bytes!=std::optional{bytes}||!published->stamp||published->stamp->st_dev!=fd.st_dev||published->stamp->st_ino!=fd.st_ino||!p->current()){return err(ErrorCode::Conflict,"Published Azureus diversification changed");}return {};}catch(...){return err(ErrorCode::Io,"Cannot save Azureus remote diversifications");}}
}
